INSERT INTO hf_directory_search(rowid,search_text)
SELECT id,search_text FROM hf_directory_genomes WHERE version='202610220000000000000006' AND genome_id IN ('GCF_000005845.2','GCF_000015005.1','GCF_000196035.1','GCF_000277735.2','GCF_000742975.1','GCF_003019785.1','GCF_040166795.1','GCF_051046855.1','GCF_051122735.1') AND EXISTS (SELECT 1 FROM bted_collections WHERE collection='experimental' AND version='202610310000000000000005' AND taxonomy_system='ncbi');
UPDATE hf_directory_releases SET summary_json=json_set(summary_json,
'$.counts.phylum', (SELECT json_group_object(phylum,n) FROM (SELECT phylum,count(*) n FROM hf_directory_genomes WHERE version='202610220000000000000006' GROUP BY phylum)),
'$.phyla', (SELECT json_group_array(phylum) FROM (SELECT DISTINCT phylum FROM hf_directory_genomes WHERE version='202610220000000000000006' AND phylum<>'' ORDER BY phylum)))
WHERE version='202610310000000000000005' AND status='ready' AND json_extract(summary_json,'$.storage_version')='202610220000000000000006' AND EXISTS (SELECT 1 FROM bted_collections WHERE collection='experimental' AND version='202610310000000000000005' AND taxonomy_system='ncbi');
